SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'B'), 'auffangflaechen', 'Auffangflächen (Tab. 3)', 'json', NULL, false, '§5.3, §16.3.3, §16.3.4, Tab. 3', 'Plan 3: Zeilen je Auffangfläche (Art nach Tab. 3 → e gefüllt, A_A); Σ A_A·e → sum_a_e (DIN-1989-1-04-D1); Umstellung von Gl. 1 und Ablösung der Skalare A_A/e STAGED (din1989_1-R-1).', 'imported_unverified', 'Bei der Regenwassernutzung in Haushalten gilt im allgemeinen der Grundsatz, dass möglichst alle verfügbaren Auffangflächen die nach 5.2 qualitativ geeignet sind, genutzt werden sollten. Für die Ermittlung des Ertragsbeiwertes sind Lage, Neigung, Ausrichtung und Beschaffenheit der Auffangfläche zu Berücksichtigen. Als Planungsgrundlage für Neigung und Beschaffenheit der Auffangfläche können die Werte nach Tabelle 3 verwendet werden.', 'register', '{"title":"Auffangflächen","subtitle":"§16.3.4 Tab. 3 — je Fläche Art, A_A und e","add_label":"+ Fläche","placement":"section","columns":[{"key":"label","label":"Bezeichnung","type":"text"},{"key":"art","label":"Art der Auffangfläche","type":"lookup_key","required":true,"lookup":{"table_code":"TAB3"}},{"key":"a_a","label":"A_A","type":"number","unit":"m²","required":true,"min":0,"aria_label":"Auffangfläche A_A"},{"key":"e","label":"e (Tab. 3)","type":"lookup_value","required":true,"lookup":{"table_code":"TAB3","key_column":"art","value":"e"}},{"key":"e_override","label":"abweichend","type":"boolean"},{"key":"a_e","label":"A_A·e","type":"derived","expr":"a_a * e"}],"override":{"flag_key":"e_override","applies_to":["e"],"policy":"anhaltswert"},"footer":["sum_a_e"],"note":"Bei der Regenwassernutzung in Haushalten gilt im allgemeinen der Grundsatz, dass möglichst alle verfügbaren Auffangflächen die nach 5.2 qualitativ geeignet sind, genutzt werden sollten."}'::jsonb, NULL, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'auffangflaechen') AND w.code = 'DIN-1989-1-04' AND s.code = 'DIN-1989-1';
