SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'B'), 'verbraucher', 'Verbraucher (personenbezogen, Tab. 4)', 'json', NULL, false, '§16.3.7, Tab. 4', 'Plan 3: Zeilen je Verbrauchergruppe (Typ nach Tab. 4 → P_d gefüllt, +10 l bei Waschmaschine, n Personen); Σ P_d·n·365 → bw_person (DIN-1989-1-04-D2); Ablösung der Gl.-2/3-Zeilen und der Skalare P_d/n STAGED (din1989_1-R-2).', 'imported_unverified', 'Der jährliche Betriebswasserbedarf kann aus den Bedarfswerten nach Tabelle 4 ermittelt werden. Der Betriebswasserbedarf im Haushalt setzt sich zusammen aus personenbezogenen Angaben (z. B. Toilette) nach $B W_{\mathrm{a}}=P_{\mathrm{d}} \times n \times 365$ ANMERKUNG Sollten Waschmaschinen angeschlossen werden, würde sich der personenbezogene Tagesbedarf um 10 Liter erhöhen.', 'register', '{"title":"Verbraucher (personenbezogen)","subtitle":"§16.3.7 Tab. 4 — je Verbrauchergruppe Typ, Personen, Tagesbedarf","add_label":"+ Verbrauchergruppe","placement":"section","columns":[{"key":"label","label":"Bezeichnung","type":"text"},{"key":"typ","label":"Verbraucher (Tab. 4)","type":"lookup_key","required":true,"lookup":{"table_code":"TAB4_PERSON"}},{"key":"n","label":"n (Personen)","type":"number","required":true,"min":0,"aria_label":"Anzahl der Personen n"},{"key":"p_d","label":"P_d (Tab. 4)","type":"lookup_value","required":true,"unit":"l/(Person·d)","lookup":{"table_code":"TAB4_PERSON","key_column":"typ","value":"p_d"}},{"key":"p_d_override","label":"abweichend","type":"boolean"},{"key":"waschmaschine","label":"Waschmaschine angeschlossen (+10 l)","type":"boolean"},{"key":"p_d_eff","label":"P_d wirksam","type":"derived","expr":"p_d + if(waschmaschine, lookup(''TAB4_WASCHMASCHINE'', ''waschmaschine'', ''p_d_zusatz''), 0)"},{"key":"bw_row","label":"BW_a (Zeile)","type":"derived","expr":"p_d_eff * n * 365"}],"override":{"flag_key":"p_d_override","applies_to":["p_d"],"policy":"anhaltswert"},"footer":["bw_person"],"note":"ANMERKUNG Sollten Waschmaschinen angeschlossen werden, würde sich der personenbezogene Tagesbedarf um 10 Liter erhöhen."}'::jsonb, NULL, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'verbraucher') AND w.code = 'DIN-1989-1-04' AND s.code = 'DIN-1989-1';
