SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'D'), 'tagesbedarf', 'Tagesbedarf an Betriebswasser (BW_a / 365)', 'number', 'l/d', false, '§11, §16.3.7', 'Plan 3: Ausgabe der Gleichung DIN-1989-1-04-D5; Grenze für das Hybridbehälter-Volumen (≤ halber Tagesbedarf, §11) — Gate STAGED (din1989_1-G-2), Übernahme nach DIN-1989-1-03 STAGED (din1989_1-C-2).', 'imported_unverified', 'Hybridbehälter sind in Bezug auf die Betriebswasserpumpe als Vorlagebehälter zu betrachten und entsprechend zu dimensionieren. Ihr Volumen sollte nicht größer als der halbe Tagesbedarf an Betriebswasser sein. Der Betriebswasserbedarf im Haushalt setzt sich zusammen aus personenbezogenen Angaben (z. B. Toilette) nach $B W_{\mathrm{a}}=P_{\mathrm{d}} \times n \times 365$', 'derived', NULL, NULL, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'tagesbedarf') AND w.code = 'DIN-1989-1-04' AND s.code = 'DIN-1989-1';
INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'E'), 'verkuerzt_band_beachtet', 'Verkürztes Verfahren (§16.2): Das Nutzvolumen sollte einerseits 25 l/m² bis 50 l/m² angeschlossener Auffangfläche (nicht für Gründächer) betragen und andererseits sollten 800 l bis 1000 l Nutzvolumen je Nutzer vorgesehen werden — Bedingungen (Niederschlagshöhen von 500 mm bis 800 mm je Jahr; ganzjährige häusliche Nutzung; konstante Personenzahl und Nutzung; Dachflächen als Auffangflächen) geprüft und Bänder beachtet', 'boolean', NULL, false, '§16.2', 'Plan 3: Bestätigung der §16.2-Bänder (SR-2-Bereich, keine Berechnung) — sichtbar nur im verkürzten Verfahren; V_n wird dann von Hand eingetragen.', 'imported_unverified', '- ein verkürztes Verfahren für kleine Anlagen (z. B. Ein- und Zweifamilienhäuser), bei dem keine Berechnungen durchgeführt werden müssen; Dieses Verfahren kann bei Ein- und Zweifamilienhäusern oder vergleichbar anderen Gebäuden oder Nutzungsarten angewendet werden, wenn folgende Bedingungen vorliegen: - Niederschlagshöhen von 500 mm bis 800 mm je Jahr - ganzjährige häusliche Nutzung - konstante Personenzahl und Nutzung - Dachflächen als Auffangflächen Das Nutzvolumen sollte einerseits $25 \mathrm{~V} / \mathrm{m}^{2}$ bis $50 \mathrm{~V} / \mathrm{m}^{2}$ angeschlossener Auffangfläche (nicht für Gründächer) betragen und andererseits sollten 800 l bis 1000 l Nutzvolumen je Nutzer vorgesehen werden.', 'attestation', NULL, NULL, 'bemessungsverfahren == ''verkuerzt''', NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'verkuerzt_band_beachtet') AND w.code = 'DIN-1989-1-04' AND s.code = 'DIN-1989-1';
UPDATE fields f SET widget = 'attestation', ui_config = NULL, lookup = NULL, visible_when = 'ueberlauf_versickerung == true' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND f.symbol = 'versickerung_bemessung_a138' AND w.code = 'DIN-1989-1-05' AND s.code = 'DIN-1989-1' AND f.active;
UPDATE fields f SET widget = 'attestation', ui_config = NULL, lookup = NULL, visible_when = 'ueberlauf_versickerung == true' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND f.symbol = 'whg_erlaubnis' AND w.code = 'DIN-1989-1-05' AND s.code = 'DIN-1989-1' AND f.active;
INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'C'), 'kanalart', 'Kanalart des Überlaufanschlusses (§14)', 'enum', NULL, false, '§14', 'Plan 3: Treiber der Rückstau-Logik — Mischwasserkanal schließt den Rückstauverschluss aus (Gate STAGED, din1989_1-G-1); Regenwasserkanal erlaubt ihn für Erdspeicher.', 'imported_unverified', 'Falls der Überlauf von Regenwasserspeichern der Mischwasserkanalisation oder von in Kellerräumen aufgestellten Regenwasserspeichern der Regenwasserkanalisation zugeführt wird, ist dieser rückstaufrei (siehe Bild 2) oder über eine Hebeanlage (siehe Bild 3) auszuführen. Ein Anschluss an einen Mischwasserkanal über einen Rückstauverschluss ist nicht zulässig.', 'select_one', NULL, NULL, NULL, '[{"value":"mischwasser","label_de":"Mischwasserkanalisation","order_index":0},{"value":"regenwasser","label_de":"Regenwasserkanalisation","order_index":1}]'::jsonb, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'kanalart') AND w.code = 'DIN-1989-1-05' AND s.code = 'DIN-1989-1';
INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'D'), 'inbetriebnahme_pruefpunkte', 'Geprüfte Anlagenteile bei der Inbetriebnahme (Anhang B, Nr. 1–15)', 'json', NULL, false, '§17.2, Anhang B', 'Plan 3: Mehrfachauswahl über die 15 Zeilen des Anhang-B-Protokolls (informativ); ersetzt keine Prüfung, dokumentiert sie.', 'imported_unverified', 'Über die durchgeführte Inbetriebnahme und die Übergabe der Unterlagen ist zweckmäßigerweise ein Inbetriebnahme- und Einweisungsprotokoll anzufertigen (siehe Anhang B). \hline Nr. & Anlagenteil, Apparat ${ }^{1)}$ & Bemerkungen \\', 'select_many', '{"title":"Inbetriebnahme- und Einweisungsprotokoll (Anhang B)","subtitle":"Nr. 1–15 — Anlagenteil, Apparat; Nicht zutreffendes ist zu streichen, fehlendes zu ergänzen.","note":"Die Inbetriebnahme ist durch einen Fachkundigen durchzuführen. Zur Inbetriebnahme ist ein Probelauf mit Wasser mit mehreren Schaltspielen (z. B. der Betriebswasserpumpe und der Nachspeiseeinrichtung) erforderlich. Vor, während bzw. nach diesem Probelauf sind z. B. zu prüfen:"}'::jsonb, NULL, NULL, '[{"value":"dachablaeufe","label_de":"Dachabläufe","order_index":0},{"value":"dachrinnen_regenfallrohre","label_de":"Dachrinnen, Regenfallrohre","order_index":1},{"value":"filtersysteme","label_de":"Filtersysteme","order_index":2},{"value":"regenwasserspeicher","label_de":"Regenwasserspeicher","order_index":3},{"value":"betriebswasserpumpe","label_de":"Betriebswasserpumpe","order_index":4},{"value":"nachspeisung_freier_auslauf","label_de":"Nachspeisung, Freier Auslauf","order_index":5},{"value":"systemsteuerung","label_de":"Systemsteuerung","order_index":6},{"value":"rohrleitungen","label_de":"Rohrleitungen","order_index":7},{"value":"wasserzaehler","label_de":"Wasserzähler","order_index":8},{"value":"rueckflussverhinderer","label_de":"Rückflussverhinderer","order_index":9},{"value":"rueckstauverschluesse","label_de":"Rückstauverschlüsse","order_index":10},{"value":"geruchverschluesse","label_de":"Geruchverschlüsse","order_index":11},{"value":"hebeanlage","label_de":"Hebeanlage","order_index":12},{"value":"entnahmearmaturen","label_de":"Entnahmearmaturen","order_index":13},{"value":"kennzeichnung","label_de":"Kennzeichnung Leitungen, Entnahmestellen und Hinweisschild","order_index":14}]'::jsonb, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'inbetriebnahme_pruefpunkte') AND w.code = 'DIN-1989-1-05' AND s.code = 'DIN-1989-1';
