SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'C'), 'wartungsplan', 'Inspektions- und Wartungsplan (Tab. 5)', 'json', NULL, false, '§18, Tab. 5', 'Plan 3: Katalogregister über die 17 Anlagenteile der Tab. 5 (Intervalle gefüllt, Erledigungsdatum); Zeilenzahl → wartungsplan_rows (DIN-1989-1-06-D1); die Hebeanlage-Intervalle b/c/d sind eine Zelle (din1989_1-J-2).', 'imported_unverified', 'Inspektions- und Wartungsarbeiten an Regenwassernutzungsanlagen müssen durch den Betreiber oder einen Fachkundigen in Zeitintervallen nach Tabelle 5 durchgeführt werden und für die in Tabelle 5 aufgeführten Anlagenteile in folgendem Umfang inspiziert bzw. gewartet werden. Längere oder kürzere Zeitintervalle können sich durch spezielle anlagen- und betriebstechnische Randbedingungen ergeben.', 'register', '{"title":"Inspektions- und Wartungsplan (Tab. 5)","subtitle":"§18 — je Anlagenteil Intervalle nach Tab. 5, Erledigung und Bemerkung","add_label":"+ Anlagenteil","placement":"section","columns":[{"key":"anlagenteil","label":"Anlagenteil/Apparat (Tab. 5)","type":"lookup_key","required":true,"lookup":{"table_code":"TAB5"}},{"key":"inspektion","label":"Inspektion","type":"lookup_value","lookup":{"table_code":"TAB5","key_column":"anlagenteil","value":"inspektion_intervall"}},{"key":"wartung","label":"Wartung","type":"lookup_value","lookup":{"table_code":"TAB5","key_column":"anlagenteil","value":"wartung_intervall"}},{"key":"erledigt_am","label":"erledigt am","type":"date"},{"key":"bemerkung","label":"Bemerkung","type":"text"}],"footer":["wartungsplan_rows"],"note":"Längere oder kürzere Zeitintervalle können sich durch spezielle anlagen- und betriebstechnische Randbedingungen ergeben."}'::jsonb, NULL, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'wartungsplan') AND w.code = 'DIN-1989-1-06' AND s.code = 'DIN-1989-1';
INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'C'), 'wartungsplan_rows', 'Anzahl erfasster Anlagenteile im Wartungsplan (Tab. 5 druckt 17)', 'number', NULL, false, '§18, Tab. 5', 'Plan 3: Ausgabe der Gleichung DIN-1989-1-06-D1 (count_rows über wartungsplan); Vollständigkeitsprüfung gegen 17 STAGED (kein Gate).', 'imported_unverified', 'Inspektions- und Wartungsarbeiten an Regenwassernutzungsanlagen müssen durch den Betreiber oder einen Fachkundigen in Zeitintervallen nach Tabelle 5 durchgeführt werden und für die in Tabelle 5 aufgeführten Anlagenteile in folgendem Umfang inspiziert bzw. gewartet werden.', 'derived', NULL, NULL, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'wartungsplan_rows') AND w.code = 'DIN-1989-1-06' AND s.code = 'DIN-1989-1';
UPDATE worksheet_sections ws SET visible_when = 'bemessungsverfahren != ''verkuerzt''' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE ws.worksheet_template_id = w.id AND ws.code = 'B' AND w.code = 'DIN-1989-1-04' AND s.code = 'DIN-1989-1';
